"""Доработка 14.09.26, пачка 4: согласование контента по результатам проверки —
число моделей, сквозная экономика, юридические формулировки, заглушки контактов,
цены/суммы между экранами, язык и мелкие визуальные ревью."""
import os, sys
P = os.path.join(os.path.dirname(__file__), "..", "project", "Промышленный агрегатор.dc.html")
s = open(P, encoding="utf-8").read()
N = 0
def R(old, new, n=1):
    global s, N
    c = s.count(old)
    if c != n: sys.exit(f"[{c}≠{n}] {old[:100]!r}")
    s = s.replace(old, new)
    N += 1

